[CmdletBinding()]param([string]$VCenter="VCENTER01",[string]$OutputPath=".\vmware-health.csv")
$ErrorActionPreference="Stop";try{Import-Module VMware.PowerCLI;Connect-VIServer $VCenter|Out-Null;$r=@();Get-VMHost|%{$r+=[pscustomobject]@{Check="Host";Target=$_.Name;Status=$_.ConnectionState;Details="Power=$($_.PowerState)"}};Get-Datastore|%{$f=[math]::Round(($_.FreeSpaceGB/$_.CapacityGB)*100,2);$r+=[pscustomobject]@{Check="Datastore";Target=$_.Name;Status=if($f-lt15){"Critical"}elseif($f-lt25){"Warning"}else{"Healthy"};Details="FreePercent=$f"}};$r|Export-Csv $OutputPath -NoTypeInformation;$r}finally{Disconnect-VIServer * -Confirm:$false -ErrorAction SilentlyContinue}
